steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query {
      teams {
        nodes {
          id
          name
          ... on Team {
            projects {
              nodes {
                id
                name
                issues(
                  first: 50,
                  filter: {
                    state: { operator: \"eq\", value: \"Done\" }
                    completedAt: { operator: \"eq\", value: \"2024-08-14\" }
                  }
                ) {
                  nodes {
                    id
                    identifier
                    title
                    description
                    priority
                    state {
                      name
                    }
                    completedAt
                  }
                }
              }
            }
          }
        }
      }
    }"
  }'
